import "reflect"

func TestIncrementingNonce() {
	exchange := ccxt.NewExchange().(*ccxt.Exchange)
	exchange.DerivedExchange = exchange
	exchange.InitParent(map[string]any{
		"id": "sampleexchange",
	}, map[string]any{}, exchange)
	// seed lastNonce above the current clock so two successive calls land in the same
	// tick and must return n and n + 1 deterministically (avoids a second-boundary flake)
	var seed int = 9999999999999
	ccxt.AddElementToObject(exchange.Options, "lastNonce", seed)
	var first any = exchange.IncrementingNonce()
	var second any = exchange.IncrementingNonce()
	assert(func(a, b any) bool {
		for _, p := range []*any{&a, &b} {
			for {
				switch (*p).(type) {
				case *string, *int64, *float64, *bool, *int, *[]string, *[]any, *map[string]any, *any:
					r := reflect.ValueOf(*p)
					_, again := (*p).(*any)
					if *p = nil; !r.IsNil() {
						*p = r.Elem().Interface()
					}
					if again && *p != nil {
						continue
					}
				case map[string]any, []any, []string:
					if reflect.ValueOf(*p).IsNil() {
						*p = nil
					}
				}
				break
			}
		}
		num := func(v any) (int64, float64, int) {
			switch n := v.(type) {
			case int:
				return int64(n), float64(n), 1
			case int64:
				return n, float64(n), 1
			case float64:
				return 0, n, 2
			}
			return 0, 0, 0
		}
		ia, fa, ka := num(a)
		ib, fb, kb := num(b)
		gt := (a != nil && b == nil) || (ka == 1 && kb == 1 && ia > ib) || (ka*kb > 1 && fa > fb)
		return gt
	}(first, seed), "incrementingNonce should bump past the stored lastNonce")
	assert((second == ccxt.Add(first, 1)), "two incrementingNonce calls in the same tick should return n and n + 1")
	assert(func(a, b any) bool {
		for _, p := range []*any{&a, &b} {
			for {
				switch (*p).(type) {
				case *string, *int64, *float64, *bool, *int, *[]string, *[]any, *map[string]any, *any:
					r := reflect.ValueOf(*p)
					_, again := (*p).(*any)
					if *p = nil; !r.IsNil() {
						*p = r.Elem().Interface()
					}
					if again && *p != nil {
						continue
					}
				case map[string]any, []any, []string:
					if reflect.ValueOf(*p).IsNil() {
						*p = nil
					}
				}
				break
			}
		}
		num := func(v any) (int64, float64, int) {
			switch n := v.(type) {
			case int:
				return int64(n), float64(n), 1
			case int64:
				return n, float64(n), 1
			case float64:
				return 0, n, 2
			}
			return 0, 0, 0
		}
		ia, fa, ka := num(a)
		ib, fb, kb := num(b)
		gt := (a != nil && b == nil) || (ka == 1 && kb == 1 && ia > ib) || (ka*kb > 1 && fa > fb)
		return gt
	}(second, first), "incrementingNonce should be strictly increasing")
}
